-- GidiReads Resources: member and author guides with admin-managed article content.
-- Apply only after the V5 site deployment, alongside the other held migrations.
create table if not exists public.resource_articles (
 id uuid primary key default gen_random_uuid(), slug text not null unique check (slug ~ '^[a-z0-9-]+$'),
 category text not null check (category in ('Getting started','Writing and publishing','Managing stories','Readers and engagement','Earnings and payments','Opportunities','Account and safety')),
 title text not null check (length(title) between 3 and 120), summary text not null check (length(summary) between 10 and 240),
 body text not null check (length(body) between 20 and 30000), status text not null default 'draft' check (status in ('draft','published')),
 audience text not null default 'all' check (audience in ('all','readers','authors')),
 sort_order integer not null default 100, updated_by uuid references auth.users(id) on delete set null,
 published_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
alter table public.resource_articles add column if not exists audience text not null default 'all';
alter table public.resource_articles drop constraint if exists resource_articles_audience_check;
alter table public.resource_articles add constraint resource_articles_audience_check check (audience in ('all','readers','authors'));
create index if not exists resource_articles_published_order_idx on public.resource_articles(status, audience, sort_order, title);
create table if not exists public.resource_article_revisions (
 id uuid primary key default gen_random_uuid(), article_id uuid not null references public.resource_articles(id) on delete cascade,
 changed_by uuid references auth.users(id) on delete set null, snapshot jsonb not null, created_at timestamptz not null default now()
);
create index if not exists resource_article_revisions_article_idx on public.resource_article_revisions(article_id, created_at desc);
alter table public.resource_articles enable row level security;
alter table public.resource_article_revisions enable row level security;
drop policy if exists "Published resources are readable" on public.resource_articles;
drop policy if exists "Published resources are readable by visitors" on public.resource_articles;
drop policy if exists "Published resources are readable by members" on public.resource_articles;
create policy "Published resources are readable by visitors" on public.resource_articles for select to anon using (status = 'published');
create policy "Published resources are readable by members" on public.resource_articles for select to authenticated using (status = 'published' or exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin'));
drop policy if exists "Admins manage resources" on public.resource_articles;
create policy "Admins manage resources" on public.resource_articles for all to authenticated using (exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin')) with check (exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin'));
drop policy if exists "Admins read resource revisions" on public.resource_article_revisions;
create policy "Admins read resource revisions" on public.resource_article_revisions for select to authenticated using (exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin'));
drop policy if exists "Admins add resource revisions" on public.resource_article_revisions;
create policy "Admins add resource revisions" on public.resource_article_revisions for insert to authenticated with check (exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin'));
create or replace function public.capture_resource_article_revision() returns trigger language plpgsql security definer set search_path = public, pg_temp as $$
begin
 if tg_op = 'UPDATE' then
   insert into public.resource_article_revisions(article_id,changed_by,snapshot) values(old.id,auth.uid(),to_jsonb(old));
   new.updated_at:=now();
   if new.status='published' and old.status is distinct from 'published' then new.published_at:=now();
   elsif new.status='draft' then new.published_at:=null; end if;
 elsif tg_op = 'INSERT' and new.status='published' and new.published_at is null then new.published_at:=now();
 end if;
 return new;
end; $$;
drop trigger if exists resource_article_revision_before_update on public.resource_articles;
create trigger resource_article_revision_before_update before insert or update on public.resource_articles for each row execute function public.capture_resource_article_revision();
insert into public.resource_articles(slug,category,title,summary,body,status,sort_order,published_at) values
('first-time-on-gidireads', 'Getting started', 'Getting started on GidiReads', 'A clear first guide to your account, your profile and the main areas of the platform.', '<p>Welcome to GidiReads. You can use the platform to read stories, publish your own work, meet readers and take part in opportunities when they are available.</p><h2>Set up your account</h2><ol><li>Create an account with an email address you can access.</li><li>Choose a username. This is how people can find and mention you on GidiReads.</li><li>Complete the profile details you want other members to see.</li><li>Keep your sign-in details private. GidiReads staff will never need your password.</li></ol><h2>Find your way around</h2><p>Use <a href="explore.html">Explore</a> to discover stories, <a href="library.html">Library</a> to return to stories you have saved, and your profile to manage your public information. If you publish stories, open <a href="authors-studio.html">Authors Studio</a> for your writing tools.</p><h2>Reader or author?</h2><p>You do not need to publish a story to enjoy GidiReads. You can begin as a reader and use the writing tools when you are ready. Publishing access is available through Authors Studio for accounts that can use author features.</p><h2>Something looks different?</h2><p>Some features may appear only to eligible accounts or while a programme is open. If a page says a feature is unavailable, do not assume you have done something wrong. Check the notice on that page and contact support if the message does not explain what to do.</p>', 'published', 1, now()),
('your-profile-and-settings', 'Getting started', 'Your profile and account settings', 'What your profile shows, what you can change and how to keep your account details safe.', '<p>Your profile is your public identity on GidiReads. It helps readers recognise you and find your work.</p><h2>Update your profile</h2><p>Open your account or profile page to review the details available to you, such as your display name, username, picture and biography. Save changes before leaving the page. If a field is not available, it may not be supported by the current version.</p><h2>Public and private information</h2><p>Only add information you are comfortable sharing. Your public profile is different from private account information used to manage your account. Do not put passwords, verification codes, payment details or private contact information in your biography.</p><h2>Changing your username</h2><p>If username editing is available in your account settings, follow the instructions shown there. A username may need to be unique. If your chosen name is already in use, choose another one.</p><h2>Keep your account safe</h2><p>Use a password you do not use elsewhere, sign out on shared devices and never share a one-time code. If you think someone else has accessed your account, change your password and contact the platform team.</p>', 'published', 2, now()),
('create-your-first-story', 'Writing and publishing', 'Create your first story', 'How to start a novel and complete the information readers need before they open it.', '<p>Open Authors Studio and choose <a href="create-story.html">Create Story</a>. Work through the steps and save your details as you go.</p><h2>Choose a clear title</h2><p>Use the title readers should see on the story page. Check spelling before publishing. You can update story details later if the editing controls allow it.</p><h2>Write a useful synopsis</h2><p>Tell readers what the story is about, who or what it follows and what makes the situation interesting. Keep important twists and the ending private. Avoid promises that the story does not deliver.</p><h2>Choose genres and tags carefully</h2><p>Select the genres that best describe the story. Add tags that help the right readers find it. Do not add unrelated popular tags just to attract clicks.</p><h2>Add a cover</h2><p>Use artwork you created, licensed or have permission to use. Make sure the title and important details remain readable at a small size. Do not use another author''s cover or artwork without permission.</p><h2>Save and review</h2><p>Check the title, synopsis, genre, tags and cover before you publish. A draft is not the same as a published story. Open My Stories to find your saved work and continue editing.</p>', 'published', 3, now()),
('write-and-format-chapters', 'Writing and publishing', 'Write and format chapters', 'Prepare chapters so they are comfortable to read on phones, tablets and computers.', '<p>Open <a href="my-stories.html">My Stories</a>, choose the story you want to work on and open its writing or chapter workspace.</p><h2>Give each chapter a clear heading</h2><p>Use a chapter title or number that matches the order of your story. Check that you are editing the correct chapter before saving.</p><h2>Make the text easy to read</h2><ul><li>Break long passages into paragraphs.</li><li>Start a new paragraph when the speaker changes.</li><li>Use punctuation consistently.</li><li>Avoid repeated spaces, decorative symbols and excessive capital letters.</li><li>Preview the chapter before publishing.</li></ul><h2>Save and publish</h2><p>Save your work before leaving the editor. If the chapter is still a draft, readers will not see it as a published chapter. Use the publish control only after checking the text and chapter order.</p><h2>If your work does not save</h2><p>Check your connection and wait for any saving message to finish. Copy your latest writing somewhere safe before refreshing if you are unsure whether it was saved. If the problem continues, note the story and chapter name when contacting support.</p>', 'published', 4, now()),
('story-workspace-and-metadata', 'Managing stories', 'Use Story Workspace and story details', 'Where to manage your story information, notes, planning material and chapter work.', '<p>Story Workspace brings together the tools connected to an individual story. The exact tools shown can depend on the story and the features available to your account.</p><h2>Story details</h2><p>Use the story details or metadata area to review information such as the title, synopsis, genre, tags and cover. Keep these details accurate as the story changes.</p><h2>Planning tools</h2><p>Story Bible and Author Notes are for your own planning and reference. Use them to keep character details, setting notes, plot points and reminders together. They are not a substitute for saving your actual chapter text.</p><h2>Chapter work</h2><p>Use the chapter area to create, edit, arrange and publish chapters. Check the chapter list after making changes so the reading order is correct.</p><h2>Bulk chapter import</h2><p>If a bulk import option is available in your Story Workspace, read its on-screen instructions before selecting files. Check the imported chapter titles and order carefully. Do not assume an import has published chapters unless the page confirms that it has.</p><h2>Keep a separate copy</h2><p>Keep your own copy of important manuscripts and notes. A platform account should not be your only copy of work that matters to you.</p>', 'published', 5, now()),
('edit-unpublish-and-delete-stories', 'Managing stories', 'Edit, unpublish or remove a story', 'Understand the difference between editing a story, hiding it from readers and removing it.', '<p>Before making a major change, open the correct story and read the confirmation message on the page.</p><h2>Edit a story</h2><p>Editing changes the story information or chapter text. Review the saved result after making changes, especially if readers have already seen the earlier version.</p><h2>Unpublish or hide a story</h2><p>If an unpublish or visibility control is available, use it when you need to stop new readers from accessing the story. The page should explain what happens to existing readers and saved links. If it does not, ask support before proceeding.</p><h2>Delete a story</h2><p>Deletion may be difficult or impossible to reverse. Read the confirmation carefully and keep a copy of your manuscript first. Do not delete a story simply to correct a typo; edit the story instead.</p><h2>Rights and responsibility</h2><p>You are responsible for having the rights to publish the story and its cover. If a rights concern is raised, respond through the process explained in the notice you receive.</p>', 'published', 6, now()),
('readership-and-story-statistics', 'Managing stories', 'Understand your readership and story statistics', 'What story activity can tell you and why a number may not change immediately.', '<p>Story statistics help you understand how readers are finding and engaging with your work. The information shown depends on which tracking features are active.</p><h2>Reads and views</h2><p>A view or read count is an activity measure. It does not tell you whether a reader finished the story or enjoyed it. Different pages may show different measures, so use the label beside each number.</p><h2>Likes, comments and Echoes</h2><p>These actions show different kinds of engagement. A like is a quick sign of appreciation. A comment is a written response. An Echo is a form of support. Do not treat one as a replacement for another.</p><h2>Why numbers may differ</h2><p>Some statistics update after a delay. Counts may also be filtered to remove invalid or repeated activity. If a number looks wrong for a long time, record the story title and the figure you see, then contact support.</p><h2>Use the information well</h2><p>Look for patterns over time rather than judging a story by one day''s numbers. You can use reader feedback to decide what to improve, but do not feel pressured to change a story just to chase a metric.</p>', 'published', 7, now()),
('likes-comments-and-following', 'Readers and engagement', 'Likes, comments and following authors', 'How readers show appreciation and keep up with stories and writers.', '<p>GidiReads has different ways to help readers respond to stories and stay connected with writers.</p><h2>Story likes</h2><p>Use the like control on a story when you want to show that you appreciate it. If you tap it again and the page allows it, your like may be removed. A like is not a paid action.</p><h2>Comments</h2><p>Use comments to share a thoughtful response or ask a relevant question. Keep discussion respectful. Do not post personal information, harassment, threats or material that breaks the platform rules. Report content that concerns you rather than starting an argument.</p><h2>Following</h2><p>Follow an author or use the available story-saving tools to make it easier to return to work you enjoy. Following does not give you permission to copy, republish or distribute an author''s work.</p><h2>Notifications</h2><p>Check Notifications for activity and updates. Some alerts may depend on your settings, the feature involved and whether notifications are enabled on your device.</p>', 'published', 8, now()),
('echoes-and-supporting-authors', 'Readers and engagement', 'Echoes and supporting authors', 'What Echoes mean, how to send them and what readers should check first.', '<p>Echoes are GidiReads'' way for readers to show support for authors. They are different from G Coins, which are used for paid chapter access when that feature is enabled.</p><h2>Sending an Echo</h2><p>Where the Echo control is available, choose whether you want to support a chapter or the whole novel if the page offers both choices. Review the amount and recipient before confirming. The page should show the result after a successful action.</p><h2>Free and purchased Echoes</h2><p>GidiReads may provide promotional or daily Echoes under the rules shown in the wallet or reward area. These are different from purchased balances. Check the balance type and any expiry or carry-over information displayed before using them.</p><h2>Can I Echo a chapter again?</h2><p>Follow the limits and eligibility message shown by the Echo control. If the platform says a chapter is eligible, you can use the available options. If it says you have already supported it or are not eligible, do not try to work around the limit.</p><h2>Check your activity</h2><p>Review your wallet or activity history when available. If an Echo is missing or appears more than once, do not repeat the action. Contact support with the story, chapter and approximate time.</p>', 'published', 9, now()),
('gifts-and-gift-catalogue', 'Readers and engagement', 'Send a gift to an author', 'Find a gift, choose the right author and check the details before sending.', '<p>Gifts let readers send an item of appreciation to an author through the gift catalogue.</p><h2>Choose a gift</h2><p>Open the gift area from the place where gifting is offered. Review the gift name, image, description and Echo cost before choosing it. Gift costs are shown in Echoes, not G Coins. Gifts use Purchased Support Echoes, not G Coins, free appreciation Echoes or promotional Echoes.</p><h2>Choose the recipient</h2><p>Search for the author''s GidiReads username or display name. Check the result carefully so you do not send a gift to the wrong person. If the author does not appear, check the spelling and try the username.</p><h2>Confirm the gift</h2><p>Review the recipient and cost before sending. A successful send should show a confirmation. If the request fails, check your balance and connection before trying again.</p><h2>Gift problems</h2><p>If your balance changed but the gift is not shown, do not send it again straight away. Save the error message and contact support with the recipient name and gift details.</p>', 'published', 10, now()),
('coins-pass-and-wallet', 'Earnings and payments', 'G Coins, GidiPass and your wallet', 'A simple explanation of the platform''s reading currency, access pass and wallet records.', '<p>Your wallet may show different balances and records. Each has a separate purpose.</p><h2>G Coins</h2><p>G Coins are intended for paid chapter access where paid chapters have been approved and the payment system is active. They are not the same as Echoes.</p><h2>Echoes</h2><p>Echoes are used to support authors and send gifts where those features are available. A free or promotional Echo reward is not the same as a purchased balance.</p><h2>GidiPass</h2><p>GidiPass is an access product for the benefits described on its purchase or membership page. Always read the current terms and duration before subscribing.</p><h2>Current payment availability</h2><p>Real-money purchases, paid chapter checkout, subscriptions and cash payouts are not active until GidiReads has connected and tested its payment provider and published the relevant terms. A balance or pricing screen does not mean a real-money payment is currently available. Do not send money to anyone claiming they can activate a wallet manually.</p><h2>Wallet history</h2><p>When transaction history is available, use it to review credits, debits and their descriptions. If you see an unfamiliar entry, contact support rather than trying to change your balance yourself.</p>', 'published', 11, now()),
('contracts-and-paid-chapters', 'Earnings and payments', 'Contracts, paid chapters and your rights', 'What a GidiReads contract means and what to check before accepting an offer.', '<p>A contract is a written agreement between the author and GidiReads for the specific story and rights described in that agreement. A story is not contracted simply because it is popular or because an offer is discussed.</p><h2>Read the whole offer</h2><p>Check the story covered by the contract, the rights requested, the term, payment terms, responsibilities, termination rules and how disputes are handled. Ask questions about anything you do not understand before accepting.</p><h2>Contracts are story-specific</h2><p>Do not assume an agreement for one novel automatically covers your other stories. Check the exact title and scope in the contract.</p><h2>Paid chapter access</h2><p>Only stories approved for paid-chapter monetisation with the correct contract scope should have paid chapter settings. Even then, real-money purchases remain unavailable until the payment system is activated and tested.</p><h2>Your rights</h2><p>Do not sign away rights you do not intend to grant. If you are unsure what a clause means, seek independent advice before signing. Keep a copy of the final agreement and any written changes.</p>', 'published', 12, now()),
('earnings-and-payouts', 'Earnings and payments', 'Creator earnings and payouts', 'Where earnings records belong and what must be ready before withdrawals can begin.', '<p>The Creator Earnings area is intended to show eligible earnings, ledger records and payout requests for creators who have an active agreement.</p><h2>Who can earn?</h2><p>Earnings depend on an approved monetisation arrangement, the activity covered by that arrangement and the terms in your contract. Having an author account alone does not create an entitlement to payment.</p><h2>Review your records</h2><p>When the feature is active for your account, check the period, source and status of each entry. Keep your own records and report entries you do not recognise.</p><h2>Withdrawals</h2><p>Cash payouts are not active until GidiReads has configured a payment provider, verified the payout process and published payout rules. Do not submit bank details through an unofficial message or pay a person to release your earnings.</p><h2>Currency</h2><p>Use the currency and conversion information shown in the official payout terms when they are published. Do not assume a displayed estimate is a confirmed amount you can withdraw.</p>', 'published', 13, now()),
('find-and-apply-for-opportunities', 'Opportunities', 'Find and apply for opportunities', 'How to read an opportunity, check whether you qualify and submit an application.', '<p>Open <a href="opportunities.html">Opportunities</a> from Authors Studio to see programmes currently listed for authors and creators.</p><h2>Read the full details</h2><p>Open an opportunity and check its purpose, who can apply, opening and closing dates, required materials, word limits, rights terms and selection process. Do not rely only on the short card summary.</p><h2>Check eligibility</h2><p>Make sure your account and story meet every listed requirement before applying. If a requirement is unclear, ask the programme team before the deadline.</p><h2>Submit your application</h2><p>Complete every required field, attach or select the requested work and review your answers. Submit before the closing time shown on the opportunity page. Keep the confirmation or application status for your records.</p><h2>After applying</h2><p>Check the opportunity page and your notifications for updates. A submitted application is not the same as acceptance. The programme team may review, request information or update the status.</p>', 'published', 14, now()),
('holiday-hearts-entry-guide', 'Opportunities', 'Holiday Hearts: preparing and submitting an entry', 'A practical guide to the Holiday Hearts story contest and its entry requirements.', '<p>Holiday Hearts is a GidiReads writing opportunity. The live opportunity page is the final source for its current dates, prompt, word limits, eligibility rules and entry status. Always read that page before preparing your submission.</p><h2>Prepare your story</h2><p>Read the current prompt and judging information. Make sure the story fits the theme and that you own or control the rights needed to submit it. Check the minimum and maximum word counts shown on the opportunity.</p><h2>Submit through the entry flow</h2><p>The entry flow allows one entry per author. If you need to correct something, contact the programme team instead of creating another entry. Use the entry action on the Holiday Hearts opportunity page. The submission flow may ask you to create or select a story, provide a title and synopsis, confirm the required rights statements and add chapters. Follow the instructions shown in the form.</p><h2>Before you submit</h2><ul><li>Check the title and synopsis.</li><li>Check that the correct chapters are included and in the right order.</li><li>Make sure the entry meets the current word limit.</li><li>Read and confirm every required eligibility and rights statement honestly.</li><li>Submit before the deadline and look for a confirmation.</li></ul><h2>After submission</h2><p>Use the opportunity page to check your entry status. If entries are reviewed, shortlisted or selected as finalists, the status should be updated through the programme process. Finalists and winners are determined by the published rules, not by private messages.</p><h2>Need to change an entry?</h2><p>Do not create a second entry to replace the first unless the opportunity page explicitly allows it. Contact the programme team and include your entry title and account username.</p>', 'published', 15, now()),
('opportunity-status-and-results', 'Opportunities', 'Application status, finalists and results', 'What common application stages mean and where to look for official decisions.', '<p>Your opportunity application may move through several stages. The exact labels and process depend on the programme.</p><h2>Submitted</h2><p>Your application has been sent. This does not mean it has been approved.</p><h2>Under review</h2><p>The programme team is checking the application against its requirements. You may need to wait for an update.</p><h2>Approved or accepted</h2><p>The application has passed the relevant review stage. Read any next steps carefully; approval may still require you to complete another action.</p><h2>Finalist</h2><p>For a contest that uses finalists, this means the entry has been selected for the finalist stage under the published process. It does not by itself mean the entry has won.</p><h2>Winner or placement</h2><p>Final results should be published through the official opportunity page or an official GidiReads announcement. Check the listed placements and any instructions for winners.</p><h2>Appeals or questions</h2><p>Use the appeal or contact route described in the opportunity rules. Include the opportunity name, entry title and a clear explanation. Keep your message respectful and do not share private application details publicly.</p>', 'published', 16, now()),
('notifications-and-announcements', 'Getting started', 'Notifications and announcements', 'Where to find account alerts and official platform updates.', '<p>Notifications help you keep track of activity connected to your account. Announcements share information from GidiReads.</p><h2>Open Notifications</h2><p>Use the notification bell or Notifications page. Unread alerts may be marked differently from alerts you have already opened. If a mark-as-read control is shown, use it after reviewing the alert.</p><h2>Push notifications</h2><p>Push alerts depend on browser or device permission, a supported browser and an active GidiReads notification service. Allow notifications only on a device you trust. You can change permission in your browser or device settings.</p><h2>Official announcements</h2><p>Check the announcement itself for its date, audience and any links. GidiReads will not ask you to share your password or verification code in an announcement.</p><h2>You did not receive an alert</h2><p>Open the Notifications page directly and check your device permissions. Some messages may not be sent as push alerts. The official page or announcement remains the place to confirm important information.</p>', 'published', 17, now()),
('communities-and-conduct', 'Readers and engagement', 'Communities and respectful participation', 'How to take part in discussions and what to do when a community interaction goes wrong.', '<p>Communities are places to discuss stories, writing and shared interests. Each community may have its own topic and rules.</p><h2>Take part thoughtfully</h2><p>Stay on topic, respect different opinions and give useful feedback. Criticise ideas or writing choices without attacking the person who made them.</p><h2>Protect your privacy</h2><p>Do not post passwords, private addresses, financial details, private conversations or another person''s personal information. Ask before sharing someone else''s work or messages.</p><h2>Report a concern</h2><p>Use the report option when a post or account breaks the rules or makes you feel unsafe. Include a clear reason. Do not retaliate or encourage others to target the person.</p><h2>Moderation</h2><p>Moderators may review reports and take action under the platform rules. A report is a request for review, not a promise that a particular outcome will follow.</p>', 'published', 18, now()),
('privacy-security-and-reporting', 'Account and safety', 'Privacy, account security and reporting', 'Protect your information and report content or behaviour that concerns you.', '<p>Keep your account and personal information safe while using GidiReads.</p><h2>Never share sign-in codes</h2><p>Do not give anyone your password, one-time code or account recovery link. Staff should not ask you to send these details in a chat or email.</p><h2>Think before you post</h2><p>Information on a public profile, story, comment or community post may be seen by other people. Do not publish private information about yourself or anyone else.</p><h2>Report content or an account</h2><p>Use the report control where it is available. Choose the closest reason and explain what happened. Include the relevant story, chapter, comment or username so the team can find it.</p><h2>What happens next?</h2><p>The moderation team reviews reports under the platform rules. It may need time or more information. Do not assume that a report has been resolved until you receive an update or can see the result.</p><h2>Account access problem</h2><p>If you cannot sign in, use the account recovery option on the sign-in page. If you think your account has been taken over, secure your email account too and contact GidiReads through an official channel.</p>', 'published', 19, now()),
('troubleshooting-common-problems', 'Account and safety', 'Fix common problems on GidiReads', 'Simple checks for pages that do not load, changes that do not save and actions that fail.', '<h2>A page keeps loading</h2><p>Check your internet connection, refresh once and try again. If the problem continues, note the page name and time. Do not repeatedly submit the same form while it is still processing.</p><h2>Your story or chapter is missing</h2><p>Check that you are signed into the correct account and open My Stories. Confirm whether the story is a draft, published or hidden. If it is still missing, contact support with the title.</p><h2>Your changes did not save</h2><p>Wait for the save message. If you are unsure, copy your latest text before refreshing. Reopen the page and check whether the change appears.</p><h2>A gift or Echo did not go through</h2><p>Check your balance and activity history before trying again. If the balance changed but the action is missing, keep the error message and contact support.</p><h2>You cannot apply for an opportunity</h2><p>Check the opening and closing dates, account eligibility, word count and required fields. If you believe you qualify but the form still blocks you, contact the programme team before the deadline.</p><h2>What to include when asking for help</h2><p>Tell us the page you were using, what you were trying to do, what happened instead and the exact error message if one appeared. Never include your password, verification code or full payment details.</p>', 'published', 20, now()),
('reading-library-and-lists', 'Readers and engagement', 'Your library and reading lists', 'Save stories you want to return to and keep your reading organised.', '<p>Your Library helps you return to stories you have saved or started reading. Reading lists let you organise stories in a way that makes sense to you.</p><h2>Save a story</h2><p>Use the save or add-to-library control on a story page when it is available. Check your Library to make sure the story appears there.</p><h2>Create and manage lists</h2><p>Open the reading-list area and follow the controls to create a list, add stories or remove them. Choose a name that helps you remember what the list is for. If a list can be shared, check its visibility before sharing it.</p><h2>Continue reading</h2><p>Open a story from your Library or reading list. Your reading position may be saved when the reading progress feature is active. If you cannot find your place, open the chapter list and choose the chapter you last read.</p><h2>Saved does not mean owned</h2><p>Saving a story does not give you ownership of the writing or permission to copy, download, distribute or republish it.</p>', 'published', 21, now()),
('daily-rewards-tasks-and-echoes', 'Readers and engagement', 'Daily rewards and tasks', 'How daily claims, tasks and reward history work, and how to check what you received.', '<p>GidiReads may offer daily rewards and tasks that give eligible members promotional benefits for using the platform.</p><h2>Daily claim</h2><p>Open the daily reward area and read the timer and claim message. A claim is available only when the page says it is ready. The timer shows when the next claim can be made. If the page shows a carry-over or streak rule, follow the rule displayed there.</p><h2>Tasks</h2><p>Open the task list and read the requirement before starting. Some tasks are completed by an action on GidiReads; others may need you to reach a stated milestone. A task is not complete until the platform confirms it.</p><h2>Reward history</h2><p>Check the history or wallet record to confirm what was awarded. Rewards may be promotional and can have separate rules from purchased balances. They are not cash and should not be treated as withdrawable earnings.</p><h2>A task did not count</h2><p>Check that you completed the exact action and that the task is still active. Allow a short time for the record to update. If it remains missing, contact support with the task name and the date you completed it.</p>', 'published', 22, now()),
('badges-milestones-and-achievements', 'Readers and engagement', 'Badges, milestones and achievements', 'What profile badges and milestones recognise and how to check your progress.', '<p>Badges and milestones recognise certain activities or achievements on GidiReads. The requirements depend on the badge or milestone.</p><h2>Earn a badge</h2><p>Open the badge or achievement area to read the requirement. Some badges may be awarded automatically after the platform confirms an activity. Others may be connected to a contest, task or membership.</p><h2>Show or hide badges</h2><p>If your profile offers a badge-visibility setting, use it to choose which earned badges other people can see. Hiding a badge does not mean you have lost it.</p><h2>Membership badges</h2><p>A badge that records an achievement you have earned is different from a badge that shows an active subscription or membership. Check the label and membership terms to understand what it represents.</p><h2>Progress has not updated</h2><p>Some achievements are checked after an action is recorded. If your progress does not change, review the requirement and wait for the activity to sync. Contact support if the record still appears incorrect.</p>', 'published', 23, now()),
('creators-and-adaptation-opportunities', 'Opportunities', 'Creators and adaptation opportunities', 'Understand the creator role and how adaptation opportunities differ from writing and publishing.', '<p>On GidiReads, an author writes and publishes stories. A creator is someone interested in finding stories that may be suitable for an adaptation project, such as a screen, audio or other creative adaptation.</p><h2>Being a creator</h2><p>Creator access and verification may be required before some creator features are available. Follow the verification instructions shown in your account. Never send passwords or sign-in codes to someone claiming to verify you.</p><h2>Find an opportunity</h2><p>Read the full opportunity details, including the type of adaptation being considered, eligibility, rights requested, selection process and deadline. Do not assume that viewing a story or contacting its author gives you adaptation rights.</p><h2>Rights and permission</h2><p>Story rights remain with the person or organisation that owns them unless a valid agreement says otherwise. An adaptation must not begin until the necessary rights and permissions have been agreed in writing by the people who can grant them.</p><h2>Authors</h2><p>If someone approaches you about adapting your story, check who they are, what they want to make, which rights they need, how long they need them and what payment or credit is offered. Do not accept an unclear offer.</p>', 'published', 24, now()),
('contract-centre-application', 'Earnings and payments', 'Apply through the Contract Centre', 'What the contract application asks for and what happens after you submit it.', '<p>Open the Contract Centre from Authors Studio. The application is about a specific story, not a request to monetise every story on your account.</p><h2>Prepare before you begin</h2><p>Make sure the story details and chapters are up to date. You may be asked about the story, its publication history, your rights, readership, plans and readiness for a contract review.</p><h2>Answer the questions carefully</h2><p>Give honest and complete answers. If a question does not apply, use the option provided or explain why. Do not guess figures or claim rights you do not have.</p><h2>Review and submit</h2><p>Read your answers before submitting. The application page explains that applying does not guarantee acceptance or an offer. The GidiReads team reviews the story and decides whether an offer is appropriate.</p><h2>After you submit</h2><p>Check the Contract Centre for your application status and any offer or request for more information. Read the full terms before accepting. You can ask questions before making a decision.</p>', 'published', 25, now()),
('reader-paid-chapter-access', 'Earnings and payments', 'Paid chapters and chapter access', 'How paid chapter access is intended to work and what is currently unavailable.', '<p>Some stories may be approved for paid chapter access under a specific creator agreement. A price shown on a chapter does not by itself mean that checkout is active.</p><h2>Before unlocking</h2><p>When paid access is active, the story page should show which chapter is paid and the G Coin price. Review the amount and confirm that you want to unlock that chapter.</p><h2>Current availability</h2><p>Real-money purchases and paid chapter checkout are not active until GidiReads has connected and tested its payment provider. Do not send money outside the platform to unlock a chapter.</p><h2>Already unlocked?</h2><p>When purchase records are active, an eligible chapter you have already unlocked should remain available under the published rules. If access is missing, check that you are signed into the same account and contact support with the story and chapter name.</p>', 'published', 26, now()),
('language-currency-and-regional-settings', 'Getting started', 'Language, currency and regional information', 'How to understand language and currency displays while GidiReads expands to more regions.', '<p>GidiReads is being built for readers and writers in different places. Some parts of the platform may show regional settings or currency information as those features become available.</p><h2>Language</h2><p>If a language selector is shown, choose the language you want to use and check whether the page updates. A language setting may not translate every story, comment or user-written post.</p><h2>Currency</h2><p>Use the currency clearly shown beside a price or payment term. Do not assume that every displayed amount has been converted to your local currency. Check the official terms before making a payment or accepting a payout.</p><h2>Regional availability</h2><p>Payment methods, payout options and some opportunities may depend on location and local requirements. If a feature is not available in your region, follow the notice on the page rather than using another person''s payment details.</p>', 'published', 27, now()),
('verification-and-account-eligibility', 'Account and safety', 'Verification and account eligibility', 'Why a feature may ask you to verify details and how to complete checks safely.', '<p>Some GidiReads features may be limited to accounts that meet specific requirements. A verification check helps the platform confirm that an account is eligible for that feature.</p><h2>Follow the official process</h2><p>Start verification only from the relevant GidiReads page. Read what information is requested and why it is needed. If the page does not explain the request, pause and contact the platform team.</p><h2>Protect your information</h2><p>Never share your password, one-time code or account recovery link. Do not send identity or payment documents to an unofficial social media account or personal number.</p><h2>Pending or declined checks</h2><p>If a check is pending, wait for the status to update. If it is declined, read the reason and any appeal instructions. Do not create duplicate accounts to get around an eligibility decision.</p>', 'published', 28, now()),
('set-chapter-prices', 'Earnings and payments', 'Set chapter prices in Authors Studio', 'Who can set a chapter price, where to find the setting and what the price means right now.', '<p>Chapter pricing is only for a story that has been approved for paid-chapter monetisation and has an accepted contract that includes the paid-chapter scope.</p><h2>Open Chapter Pricing</h2><p>Open Authors Studio and choose Chapter Pricing from the menu. Select the story, then select the chapter you want to price. The page loads the saved price when one exists.</p><h2>Choose a price</h2><p>Use the price range shown on the page. In the current setup, chapter prices are limited to 10–100 G Coins. Save the price and wait for the confirmation message. If the story is not approved for paid chapters, do not try to set a price for it.</p><h2>Important: purchases are not active yet</h2><p>Saving a chapter price does not turn on checkout. Real-money payments and paid chapter purchases remain disabled until the payment provider has been connected, configured and tested. Readers must not be asked to pay outside GidiReads.</p><h2>Change or check a price</h2><p>Return to Chapter Pricing, select the same story and chapter, and review the saved amount. If you cannot see the story or chapter, check that you own it and that the contract approval is in place.</p>', 'published', 29, now())
