update public.resource_articles set audience='authors' where slug in (
 'create-your-first-story','write-and-format-chapters','story-workspace-and-metadata','edit-unpublish-and-delete-stories',
 'readership-and-story-statistics','contract-centre-application','set-chapter-prices','contracts-and-paid-chapters',
 'earnings-and-payouts','holiday-hearts-entry-guide'
