update public.resource_articles set audience='all' where audience is distinct from 'authors' and slug not like 'reader-%';

insert into public.resource_articles(slug,category,title,summary,body,status,sort_order,published_at,audience) values
('reader-create-account','Getting started','Create an account or log in','How to join GidiReads, sign in again and get back into your account.',$reader1$<p>You can read public stories without publishing anything. An account lets you follow writers, save stories and use the features that need a signed-in member.</p><h2>Create an account</h2><ol><li>Open the GidiReads home page and choose Log in.</li><li>Choose the option to create an account.</li><li>Enter an email address you can open and choose a username and password.</li><li>Follow any email confirmation step shown on the page.</li><li>Return to GidiReads and log in.</li></ol><h2>Log in again</h2><p>Choose Log in and enter the email and password linked to your account. If you are using a shared phone or computer, do not save your password in the browser.</p><h2>You cannot remember your password</h2><p>Choose Forgot password on the sign-in form. Enter your account email and check your inbox, including the spam folder. Use the reset link sent by GidiReads. If no message arrives, check that the email address is correct and try again later.</p><h2>Still cannot get in?</h2><p>Do not create another account just to get around a sign-in problem. Contact GidiReads support and tell us the username and the step where you get stuck. Never send your password or a reset code.</p>$reader1$,'published',30,now(),'readers'),
('reader-find-stories','Getting started','Find stories to read','Use Explore to look for stories by title, genre and the details shown on each story card.',$reader2$<p>Open <a href="explore.html">Explore</a> to browse stories on GidiReads. You can look through the collections on the page or use the search and filters that are available.</p><h2>Search for a story</h2><p>Enter a title, author name or a word that describes the kind of story you want. If the result list is too broad, try a more specific word or choose a genre filter.</p><h2>Check the story before opening it</h2><p>Read the title, synopsis, genre and tags. These details help you decide whether the story is a good match. A cover or a high read count does not guarantee that you will enjoy a story.</p><h2>Open the story</h2><p>Select the story card to open its page. Read the description and check the chapter list before you begin. If a story is not available, it may have been unpublished, removed or limited by its author or the platform.</p><h2>You cannot find a story</h2><p>Check the spelling of the title or author's username. Try a shorter search. If you have its direct link and it no longer opens, the story may no longer be public.</p>$reader2$,'published',31,now(),'readers'),
('reader-read-and-change-chapters','Readers and engagement','Open a story and move between chapters','How to start reading, choose another chapter and return to a story later.',$reader3$<p>Open a story from Explore, a writer's profile or your Library. On the story page, read the synopsis and open the chapter list.</p><h2>Start reading</h2><p>Choose the first available chapter or the chapter you want to read. Use the reading controls on the page to move to the next or previous chapter when they are available.</p><h2>Choose a different chapter</h2><p>Open the chapter list and select the chapter title. Check the chapter number before opening it so you do not skip part of the story by mistake.</p><h2>Return later</h2><p>Add the story to your Library or a reading list so you can find it again. If your reading position is not restored automatically, open the chapter list and choose the last chapter you remember reading.</p><h2>A chapter will not open</h2><p>Check that you are signed in if the page asks you to do so. If the chapter is marked as paid, read the paid-access notice. Paid checkout is not active until GidiReads announces that payments are ready. Do not pay someone outside the platform for access.</p>$reader3$,'published',32,now(),'readers'),
('reader-follow-like-and-comment','Readers and engagement','When likes, follows or comments do not work','Simple checks to try when an interaction does not save or appear on the page.',$reader4$<p>If a like, follow or comment does not appear, check the page before trying the action again.</p><h2>A like did not change</h2><p>Make sure the page finished loading and check whether the like count or button changed. Refresh the story page once. If the like still does not appear, sign in again and try later.</p><h2>A follow did not save</h2><p>Open the writer's public profile and check the button. If it still says Follow, try once more when your connection is stable. If it says Following, the action has already been saved.</p><h2>A comment is missing</h2><p>Check whether the comment form showed a success message. If it did not, copy your comment before refreshing, then check your connection and try again. A comment may also be hidden while it is reviewed under the platform rules.</p><h2>Keep interactions respectful</h2><p>Do not post threats, harassment or private information. If content concerns you, use the report option instead of starting an argument.</p><h2>Still not working?</h2><p>Note the story title, the action you tried and any message shown on the page. Contact support with those details. Never send your password or sign-in code.</p>$reader4$,'published',33,now(),'readers'),
('reader-send-echoes-and-gifts','Readers and engagement','When an Echo or gift does not go through','What to check before you try again if an Echo or gift fails.',$reader5$<p>Do not repeat an Echo or gift straight away if the page shows an error. First check whether the action was recorded.</p><h2>Check the balance and activity</h2><p>Open My GidiReads and review the wallet or activity record. Look for a new entry that matches the amount and the time of your action.</p><h2>If the balance did not change</h2><p>Check your internet connection and whether the feature is available on that page. Try again only after the page has loaded normally and you are sure the first request did not go through.</p><h2>If the balance changed but the action is missing</h2><p>Do not send it again. Save the error message, note the story or chapter, and contact support with the approximate time and transaction details.</p><h2>If you chose the wrong recipient</h2><p>Contact support as soon as possible with the recipient username, gift name and transaction details. Do not ask another member to share private account information.</p><h2>Remember</h2><p>Gift costs are shown in Echoes, not G Coins. Never pay another member or send your password to someone who offers to fix a failed transaction.</p>$reader5$,'published',34,now(),'readers'),
('reader-wallet-and-activity','Earnings and payments','Check your wallet and activity','Where to review your balances and what to do if a wallet record looks wrong.',$reader6$<p>Open <a href="my-gidireads.html">My GidiReads</a> and look for the wallet and activity records shown on your account.</p><h2>Understand the balance names</h2><p>G Coins are intended for paid chapter access when that service is active. Echoes are used to support writers. GidiPass is an access or membership feature. These balances and benefits have different rules, so check the label beside each one.</p><h2>Check a recent record</h2><p>Read the date, description and amount. If you do not recognise an entry, do not try to change the balance yourself. Save the details and contact support.</p><h2>Your balance changed but the action is missing</h2><p>Do not repeat the action straight away. Check the activity list and keep any reference number or error message. Send those details to support so the team can look into it.</p><h2>Can you withdraw a wallet balance?</h2><p>Wallet balances are not the same as creator earnings. Do not assume that G Coins or Echoes can be withdrawn as cash.</p><h2>Payments are not active yet</h2><p>Real-money purchases and paid chapter checkout remain unavailable until GidiReads connects and tests its payment provider. Do not send money to another member or staff account to top up a balance.</p>$reader6$,'published',35,now(),'readers'),
('reader-notifications-and-updates','Getting started','Fix notification problems','What to check when an alert is missing, unread or does not open.',$reader7$<p>Open <a href="notifications.html">Notifications</a> to check whether the alert is in your account.</p><h2>The unread count looks wrong</h2><p>Open the Notifications page and check the list itself. If an alert is still marked unread, use the mark-as-read control when it is shown. Refresh the page if the count does not update.</p><h2>An alert will not open</h2><p>Open the notification again after checking your internet connection. If its link no longer works, the story or page may have changed. Use Explore or the writer's profile to find the item again.</p><h2>You did not receive a push alert</h2><p>Check whether your browser or device allows notifications for GidiReads. Push alerts also depend on the platform notification service being active. You can still open Notifications directly even when push alerts are off.</p><h2>You did not receive an announcement</h2><p>Announcements may be sent only to selected members. Check the audience and date shown on the announcement. Not every announcement is sent as a push alert.</p><h2>Still missing?</h2><p>Note the type of alert you expected and when it should have arrived. Contact support if it is important and does not appear in your Notifications page.</p>$reader7$,'published',36,now(),'readers'),
('reader-join-community','Readers and engagement','Join a GidiReads community','How to take part in community spaces and help keep them welcoming.',$reader8$<p>Communities give members a place to talk about stories and shared interests. Open the community area and read the description and rules before joining or posting.</p><h2>Before you join</h2><p>Check the community topic, who can take part and whether it has any extra rules. Some spaces may be official GidiReads communities, while others may be created by members.</p><h2>Post or reply</h2><p>Choose the relevant discussion area, write a clear message and check it before posting. Keep replies connected to the topic. Respect other members even when you disagree.</p><h2>Report a problem</h2><p>If a post or member makes the space unsafe or breaks the rules, use the report option when it is available. Include enough information for the moderation team to find the content.</p><h2>Access or posting is blocked</h2><p>A community may be private, paused or limited by its rules. Read the message shown on the page. Do not create another account to get around a restriction.</p>$reader8$,'published',37,now(),'readers'),
('reader-public-profile-and-reading-lists','Getting started','Your public profile and reading lists','Choose what other members can see and keep the stories you save organised.',$reader9$<p>Your public profile helps other members recognise you. It may show your username, display name, biography, public badges, public reading lists and activity that you have chosen to share.</p><h2>Review your profile</h2><p>Open your profile and use Edit profile or Account settings to change the details the page lets you update. Check the public view after saving so you know what other people can see.</p><h2>Keep private details private</h2><p>Do not put your email password, sign-in codes, home address, payment details or other private information in your biography or public lists.</p><h2>Reading lists</h2><p>Use your Library and reading-list controls to organise stories. If a list has a public or private setting, check it before sharing. A private list should not be visible to other members.</p><h2>Badges</h2><p>If badge visibility settings are available, choose which earned badges you want to show. Hiding a badge does not remove the achievement from your account.</p>$reader9$,'published',38,now(),'readers'),
('reader-report-content-or-a-profile','Account and safety','Report a story, comment or profile','How to report something that concerns you and what information to include.',$reader10$<p>Use the report option when a story, comment or profile appears to break GidiReads rules or creates a safety concern.</p><h2>Open the report option</h2><p>On the relevant story, comment or public profile, look for Report. Choose the reason that best matches the issue and follow the form shown on the page.</p><h2>Give useful details</h2><p>Explain what happened in a few clear sentences. Include the story title, username or comment location so the team can find it. Only share information needed to explain the report.</p><h2>What happens next?</h2><p>The platform team can review the report and take action under the platform rules. A report does not guarantee that content will be removed. The team may not be able to share private details about another member or the review.</p><h2>If you cannot use the report button</h2><p>Use the support or contact route shown on GidiReads. Do not post private evidence publicly or ask other members to target the account. If someone is in immediate danger, contact local emergency services.</p>$reader10$,'published',39,now(),'readers')
on conflict (slug) do nothing;

